// OverrideScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE jro.organization_id = ? AND jro.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	buncolgen.OverrideScopeTenant(sq, ti).
//		Where(buncolgen.OverrideColumns.ID.Eq(), id)
func OverrideScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return ScopeTenant(q, OverrideColumns.OrganizationID, OverrideColumns.BusinessUnitID, ti)
}

// OverrideScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return buncolgen.OverrideScopeTenantUpdate(uq, req.TenantInfo).
//			Where(buncolgen.OverrideColumns.ID.In(), bun.List(ids))
//	})
func OverrideScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return ScopeTenantUpdate(q, OverrideColumns.OrganizationID, OverrideColumns.BusinessUnitID, ti)
}

// OverrideScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return buncolgen.OverrideScopeTenantDelete(dq, req.TenantInfo).
//			Where(buncolgen.OverrideColumns.ID.Eq(), id)
//	})
func OverrideScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return ScopeTenantDelete(q, OverrideColumns.OrganizationID, OverrideColumns.BusinessUnitID, ti)
}

// OverrideApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(buncolgen.OverrideApplyTenant(tenantInfo))
func OverrideApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return ApplyTenant(OverrideColumns.OrganizationID, OverrideColumns.BusinessUnitID, ti)
}

